describe('500 Server Error Page', () => {
  beforeEach(() => {
    cy.visit('/error');
  });

  it('should display error page when server returns 500 error', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('serverError');

    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Server Error');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');
    cy.get('[data-testid="error-code"]').should('contain', '500');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@serverError');
    cy.get('[data-testid="error-page"]').should('be.visible');
  });

  it('should handle multiple 500 errors and display retry option', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('firstError');

    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Server Error');
    cy.get('[data-testid="error-code"]').should('contain', '500');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();

    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('secondError');

    cy.wait('@secondError');
    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
